const regionConfig = {
  'us-east-1': { primary: true, redis: 'us-primary.redis.cache' },
  'eu-west-1': { primary: false, redis: 'eu-replica.redis.cache' },
  'ap-southeast-1': { primary: false, redis: 'apac-replica.redis.cache' }
};

async function getCachedUser(userId, userRegion) {
  const config = regionConfig[userRegion];
  const redis = createClient({ url: config.redis });

  // Try local replica first (eventually consistent)
  let data = await redis.get(`user:${userId}:profile`);

  if (!data) {
    // Fallback to primary for strong consistency
    const primaryRedis = createClient({
      url: regionConfig['us-east-1'].redis
    });
    data = await primaryRedis.get(`user:${userId}:profile`);
    // Backfill local cache
    await redis.set(`user:${userId}:profile`, data, { EX: 3600 });
  }

  return JSON.parse(data);
}
